mapper.select:
SELECT id,code,approve_status, seller_name, approve_user_name, name,short_name,disabled, use_org_name,group_id,group_name, create_user_name,create_time FROM customer_b2c ci WHERE ci.is_deleted=FALSE
AND ci.code ILIKE concat('%',#{params.code}::text,'%')
AND ci.name ILIKE concat('%',#{params.name}::text,'%')
AND ci.short_name ILIKE concat('%',#{params.shortName}::text,'%')
AND ci.approve_status IN
#{approveStatus}
AND ci.seller_id IN
#{item}
AND ci.id IN
#{id}
AND ci.use_org_id IN
#{useOrgId}
AND ci.create_user_id IN
#{createUserId}
AND ci.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ci.create_time
AND ci.approve_status IN
#{approve}
${params.permissionSql}
ORDER BY ci.create_time DESC

SELECT id,code,approve_status, seller_name, approve_user_name, name,short_name,disabled, use_org_name,group_id,group_name, create_user_name,create_time FROM customer_b2c ci WHERE ci.is_deleted=FALSE
AND id IN
#{id}
AND ci.code ILIKE concat('%',#{params.code}::text,'%')
AND ci.name ILIKE concat('%',#{params.name}::text,'%')
AND ci.short_name ILIKE concat('%',#{params.shortName}::text,'%')
AND ci.id IN
#{id}
AND ci.seller_id IN
#{item}
AND ci.approve_status IN
#{approveStatus}
AND ci.use_org_id IN
#{useOrgId}
AND ci.create_user_id IN
#{createUserId}
AND ci.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ci.create_time
AND ci.approve_status IN
#{approve}
${params.permissionSql}
ORDER BY ci.create_time DESC limit 50000

SELECT approve_status, count(*) FROM customer_b2c ci WHERE is_deleted=FALSE
${permissionSql}
GROUP BY approve_status

select customerId,customerName,cityId,countryId,receiverName,receiverTelNumber,firstAddress,secondAddress,zipCode,email,telNumber from ( select c."id" as customerId, c."name" as customerName, c.city_id as cityId, c.country_id as countryId, a.person as receiverName, a.tel_number as receiverTelNumber, a.address as firstAddress, a.address as secondAddress, a.zip_code as zipCode, cbc.email as email, cbc.tel_number as telNumber from customer_b2c c left join customer_b2c_address a on a.main_id = c.id and a.is_deleted = FALSE and a.disabled = FALSE and a.is_default = true left join customer_b2c_contact cbc on cbc.main_id = c.id and cbc.is_deleted = FALSE and cbc.disabled = FALSE and cbc.is_default = true where c.is_deleted = FALSE and c.disabled = FALSE
and c."id" = #{params.customerId}
and c."name" ILIKE concat('%',#{params.customerName}::text,'%')
order by case when c."name" ILIKE concat(#{params.customerName}::text,'%') THEN 1 when c."name" ILIKE concat('%',#{params.customerName}::text) THEN 2 when c."name" ILIKE concat('%',#{params.customerName}::text,'%') THEN 3 end , c."name"
) customer
